-- Recovered from the linked project's Supabase migration history.

-- Imposter playable V1: 240 active pairs, 1,578 preserved archived pairs.
begin;

create temporary table decked_imposter_v1_active(item_id uuid primary key,category_id text not null,sort_order integer not null,metadata jsonb not null) on commit drop;


do $$ declare matched integer; begin select count(*) into matched from public.content_items item join decked_imposter_v1_active selected on selected.item_id=item.id where item.game_id='imposter'; if matched<>240 then raise exception 'Imposter V1 inventory mismatch: expected 240 IDs, found %',matched; end if; end $$;

update public.content_items set lifecycle_status='archived',updated_at=now() where game_id='imposter';

update public.content_items item set lifecycle_status='active',updated_at=now() from decked_imposter_v1_active selected where item.id=selected.item_id and item.game_id='imposter';

update public.content_item_categories set enabled=false where game_id='imposter';


update public.content_item_versions version set metadata=coalesce(version.metadata,'{}'::jsonb)||selected.metadata from decked_imposter_v1_active selected join public.content_items item on item.id=selected.item_id where version.item_id=item.id and version.version=item.published_version;

update public.content_releases set status='superseded' where game_id='imposter' and status='published';


delete from public.content_release_items where release_id='9c70ec12-f9dd-58d5-878a-5075a061f51d'::uuid;


commit;
